{
  "findings": [
    {
      "ref": "[D521]",
      "area": "contact",
      "claim": "A parent reports that direct messages and party chats can be disabled with parental controls, but chats built into mini-games cannot be turned off.",
      "stance": "risk",
      "quote": "If not, children are automatically exposed to an endless stream of conversation from adults and kids, through text and audio. Roblox limits communication based on age groups, parental settings, and account protections. Chats built into the coding of specific mini-games cannot be disabled, and kids can type text on \"signs\" regardless of communication preferences."
    },
    {
      "ref": "[D521]",
      "area": "money",
      "claim": "Roblox uses Robux, a digital currency, for in-game purchases, and marketing includes ads and product placements that can lead to overspending.",
      "stance": "risk",
      "quote": "Key elements of the games include ads, official product placements, and the need for Robux, the platform's digital currency, to access gated extras. Marketing can be limited, though not completely resolved, by turning off targeted ads. Targeted ads do not appear for users under the age of 13."
    },
    {
      "ref": "[D521]",
      "area": "data",
      "claim": "Roblox may process age verification images through third-party providers, but it does not guarantee a fixed retention period for children's images.",
      "stance": "neutral",
      "quote": "Images used for age verification may be processed by third-party providers, but Roblox does not publicly guarantee a fixed retention period for the images of children."
    },
    {
      "ref": "[D521]",
      "area": "age_gating",
      "claim": "Roblox uses AI-based age estimation and verification, and mistakes can loosen protections for younger users or incorrectly restrict older users.",
      "stance": "risk",
      "quote": "Roblox uses AI-based age estimation and verification systems for some users. Users over age 13 may be asked to submit a live selfie or upload a government ID to access certain communication features. Roblox uses this information to estimate or verify a user’s age and place accounts into age-based categories. Under Roblox’s newer system, users age 5 to 8 may be placed into \"Roblox Kids\" accounts, while users age 9 to 15 may be placed into \"Roblox Select\" accounts. However, the system can make mistakes. Incorrect age estimates may loosen built-in protections, such as chat restrictions or access limits, while some adults may be incorrectly categorized as younger users and face additional restrictions."
    },
    {
      "ref": "[D521]",
      "area": "content",
      "claim": "A parent reports that extreme violence, inappropriate language, and sexually explicit content can appear in games accessible to children as young as 5.",
      "stance": "risk",
      "quote": "Extreme violence, inappropriate language, and sexually explicit content is possible (and quite likely) within the user-created games. This advanced content can be limited with the content maturity controls in settings, but much of the adult content that is labeled 5+ may still contain inappropriate content."
    },
    {
      "ref": "[D521]",
      "area": "developer_record",
      "claim": "Roblox has faced regulatory scrutiny and fines for data collection and age verification practices.",
      "stance": "risk",
      "quote": "Roblox has faced regulatory scrutiny and fines for data collection and age verification practices."
    }
  ]
}
